window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8751ea2e074e1b27"]={"versions": [{"id": "FIG-8751ea2e074e1b27", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>State Machine Diagram</em>) mit zwei orthogonalen (nebenläufigen) Regionen (<code>Main</code> und <code>Activation</code>) innerhalb des übergeordneten Composite States <code>ExecutableEntity execution-instance is schedulable</code>.</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition des Lebenszyklus und Aktivierungsverhaltens einer Instanz einer <code>ExecutableEntity</code> (z. B. <code>RunnableEntity</code> eines SWC oder <code>BswSchedulableEntity</code> des BSW-Schedulers SchM) in der AUTOSAR Runtime Environment (RTE).</li>\n<li><strong>Architektonische Einordnung:</strong> Bindeglied zwischen RTE-Aktivierungstriggern (Events, Timer, Data-Received-Events) und dem zugrundeliegenden AUTOSAR-OS-Taskmanagement. Das Modell bildet ab, wie Aktivierungsanforderungen gepuffert, entprellt (<code>minimumStartInterval</code>) und auf die Betriebssystem-Taskzustände (<em>suspended</em>, <em>ready</em>, <em>running</em>, <em>waiting</em>) synchronisiert werden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustandsraum-Variablen & Timer:</strong></li>\n<li><code>activations: int = 0</code>: Zähler für anstehende Ausführungsanforderungen (Aktivierungs-Queue).</li>\n<li><code>debounceTimer: float = minimumStartInterval</code>: Kontinuierlich laufender Hardware-/OS-Timer zur Durchsetzung des Mindestabstands aufeinanderfolgender Starts (<code>minimumStartInterval</code>).</li>\n<li><strong>Orthogonale Region <code>Main</code> (Ausführungszustände im OS-Kontext):</strong></li>\n<li><code>suspended</code>: Entität ist inaktiv; keine Ausführungsanforderung aktiv.</li>\n<li><code>to be started</code>: Aktivierung liegt vor (<code>Activation</code> in <code>activated</code>), Entität wartet auf Dispatching durch das OS.</li>\n<li><code>started</code> (Composite State):</li>\n<li><code>running</code>: Entität belegt aktuell den Prozessorkern (führt Code aus).</li>\n<li><code>waiting</code>: Entität blockiert auf ein OS-Event (<code>wait</code>, z. B. Rte_Receive/Rte_Feedback bei Server-Calls/Inter-Runnable-Synchronisation).</li>\n<li><code>preempted</code>: Unterbrochen durch höher priorisierten Task oder ISR (<code>preempt</code>).</li>\n<li><em>OS-Zuordnung:</em> Die Zustände <code>to be started</code> und <code>preempted</code> korrespondieren direkt mit dem OSEK/AUTOSAR-Task-Zustand <strong>READY</strong>.</li>\n<li><strong>Orthogonale Region <code>Activation</code> (Aktivierungs- & Entprell-Logik):</strong></li>\n<li><code>not activated</code>: Keine ausstehende Aktivierung vorhanden.</li>\n<li><code>debounce activation</code>: Aktivierung empfangen, aber Sperrzeit (<code>minimumStartInterval</code>) noch nicht abgelaufen.</li>\n<li><code>activated</code>: Ausführungsbedingung erfüllt; Entität ist startbereit für die <code>Main</code>-Region.</li>\n<li><em>Queueing-Semantik:</em> Parameter <code>queue length</code> definiert das Aktivierungslimit für die Entität (<code>activations &lt;= queue length</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Partition Life-Cycle (Umfeld-Transitionen)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Eintritt in <code>ExecutableEntity execution-instance is schedulable</code> sobald Guard <code>[RTE / SchM of the partition is running]</code> wahr ist.</li>\n<li><strong>Terminierung:</strong> Austritt in den Endzustand bei <code>[RTE / SchM of the partition is stopped]</code>.</li>\n</ol>\n<p class=\"fig-p\">#### Region <code>Activation</code> (Ereignissteuerung & Queuing)</p>\n<ol class=\"fig-list\">\n<li><strong>Erste Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>not activated</code> via Event <code>activate</code>: Aktion <code>/activations = 1</code> führt in Zustand <code>debounce activation</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung / Sperrzeit:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>debounce activation</code>: Eintreffende <code>activate</code>-Events inkrementieren bedingt den Zähler (<code>activations += (activations &lt;= queue length) 1:0</code>).</li>\n<li>Sobald Guard <code>[debounceTimer &gt;= minimumStartInterval]</code> erfüllt ist, erfolgt der Übergang in Zustand <code>activated</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Queue-Abarbeitung & Rücksprung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auf Trigger <code>start</code> (synchronisiert mit Region <code>Main</code>): Aktion <code>/activations -= 1; debounceTimer = 0</code>.</li>\n<li>Verzweigung (Choice-Pseudostate):</li>\n<li><code>[activations == 0]</code> $\\rightarrow$ Rückkehr zu <code>not activated</code>.</li>\n<li><code>[activations &gt; 0]</code> $\\rightarrow$ Übergang zu <code>debounce activation</code>, um verbleibende Aktivierungen unter Einhaltung des <code>minimumStartInterval</code> abzuarbeiten.</li>\n</ul>\n<p class=\"fig-p\">#### Region <code>Main</code> (Ausführungs-Scheduling)</p>\n<ol class=\"fig-list\">\n<li><strong>Start:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>suspended</code> nach <code>to be started</code>, sobald Guard <code>[Activation in state activated]</code> greift.</li>\n<li>Auf Event <code>start</code> $\\rightarrow$ Wechsel in <code>preempted</code> (Task wird vom OS auf <code>READY</code> gesetzt).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Scheduler weist CPU zu: <code>resume</code> $\\rightarrow$ <code>running</code>.</li>\n<li>Bei Verdrängung: <code>preempt</code> $\\rightarrow$ <code>preempted</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation / Blockierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Blocking-Aufruf (nur in Extended Tasks zulässig): <code>wait</code> $\\rightarrow$ <code>waiting</code>.</li>\n<li>Event eintritt / Ressource frei: <code>release</code> $\\rightarrow$ <code>preempted</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Beendigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ende der Runnable-Funktion: <code>terminate</code> $\\rightarrow$ Rückkehr nach <code>suspended</code>.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (<code>minimumStartInterval</code>):</strong> Das im BSW-/SWC-Dossier parametrierte <code>minimumStartInterval</code> schützt den Task vor Überlastung (z. B. bei hochfrequenten CAN-Interrupts oder Event-Triggerung). Ein zu groß gewählter Wert führt zu Latenzen bei Folgeaktivierungen; ein zu kleiner Wert kann CPU-Starvation niederpriorer Tasks begünstigen.</li>\n<li><strong>Queue-Überlauf (<code>queue length</code>):</strong> Übersteigt die Anzahl gleichzeitiger <code>activate</code>-Trigger die konfigurierte Queue-Tiefe, werden weitere Requests verworfen (<code>activations += 0</code>). Dies erfordert für sicherheitskritische Runnables eine exakte Worst-Case-Dimensionierung des Queue-Limits im System Description / EcuExtract.</li>\n<li><strong>Task-Typ-Restriktionen (Basic vs. Extended Task):</strong></li>\n<li>Die Transitionen <code>wait</code> und <code>release</code> setzen zwingend einen <strong>Extended Task</strong> (OSEK-Events) voraus.</li>\n<li>Wird eine <code>ExecutableEntity</code> auf einen <strong>Basic Task</strong> gemappt, existiert der Unterzustand <code>waiting</code> zur Laufzeit nicht; der Code darf keine blockierenden RTE-APIs aufrufen (z. B. synchrone Server-Calls mit Warteoperationen).</li>\n<li><strong>RTE-Partitions-Status:</strong> Aktivierungen und Dispatching greifen nur, wenn die Partition der SWC/BSW gestartet ist (<code>Rte_Start()</code> / SchM-Init ausgeführt). Aufrufe oder Trigger im gestoppten Zustand bleiben inaktiv.</li>\n</ul>"}, {"id": "FIG-48ed5424c916017f", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>State Machine Diagram</em>) mit drei orthogonalen (nebenläufigen) Regionen (<code>Main</code>, <code>Activation</code> und <code>ModeDisabling</code>) innerhalb des übergeordneten Composite States <code>ExecutableEntity execution-instance is schedulable</code>.</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition des Lebenszyklus, Aktivierungs- und Deaktivierungsverhaltens einer Instanz einer <code>ExecutableEntity</code> (z. B. <code>RunnableEntity</code> eines SWC oder <code>BswSchedulableEntity</code> des BSW-Schedulers SchM) in der AUTOSAR Runtime Environment (RTE).</li>\n<li><strong>Architektonische Einordnung:</strong> Bindeglied zwischen RTE-Aktivierungstriggern (Events, Timer, Data-Received-Events), Modusverwaltung (<code>ModeDeclarationGroup</code>, Modus-Deaktivierung) und dem AUTOSAR-OS-Taskmanagement. Das Modell bildet ab, wie Aktivierungsanforderungen gepuffert, entprellt (<code>minimumStartInterval</code>), durch Betriebsmodi freigegeben oder gesperrt (<code>ModeDisabling</code>) und auf die Betriebssystem-Taskzustände (<em>suspended</em>, <em>ready</em>, <em>running</em>, <em>waiting</em>) synchronisiert werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustandsraum-Variablen & Timer:</strong></li>\n<li><code>activations: int = 0</code>: Zähler für anstehende Ausführungsanforderungen (Aktivierungs-Queue).</li>\n<li><code>«continuously increasing timer» - debounceTimer: float = minimumStartInterval</code>: Kontinuierlich laufender Hardware-/OS-Timer zur Durchsetzung des Mindestabstands aufeinanderfolgender Starts (<code>minimumStartInterval</code>).</li>\n<li><strong>Orthogonale Region <code>Main</code> (Ausführungszustände im OS-Kontext):</strong></li>\n<li><code>suspended</code>: Entität ist inaktiv; keine Ausführungsanforderung aktiv.</li>\n<li><code>to be started</code>: Aktivierung liegt vor (<code>Activation</code> in <code>activated</code>), Entität wartet auf Dispatching durch das OS.</li>\n<li><code>started</code> (Composite State):</li>\n<li><code>running</code>: Entität belegt aktuell den Prozessorkern (führt Code aus).</li>\n<li><code>waiting</code>: Entität blockiert auf ein OS-Event (<code>wait</code>, z. B. Rte_Receive/Rte_Feedback bei Server-Calls/Inter-Runnable-Synchronisation).</li>\n<li><code>preempted</code>: Unterbrochen durch höher priorisierten Task oder ISR (<code>preempt</code>).</li>\n<li><em>OS-Zuordnung:</em> Die Zustände <code>to be started</code> und <code>preempted</code> korrespondieren direkt mit dem OSEK/AUTOSAR-Task-Zustand <strong>READY</strong>.</li>\n<li><strong>Orthogonale Region <code>Activation</code> (Aktivierungs-, Entprell- & Modussperr-Logik):</strong></li>\n<li>Aktive Zustände:</li>\n<li><code>not activated</code>: Keine ausstehende Aktivierung vorhanden.</li>\n<li><code>debounce activation</code>: Aktivierung empfangen, Sperrzeit (<code>minimumStartInterval</code>) läuft.</li>\n<li><code>activated</code>: Ausführungsbedingung erfüllt; Entität ist startbereit für die <code>Main</code>-Region.</li>\n<li>Deaktivierte Zustände (gesperrt durch Modus):</li>\n<li><code>disabled not activated</code>: Deaktivierter Grundzustand ohne anstehende Aktivierung.</li>\n<li><code>disabled debounce activation</code>: Deaktivierter Zustand während laufendem Debounce-Timer.</li>\n<li><code>disabled activated</code>: Deaktivierter Zustand mit bereits abgelaufenem Mindestabstand.</li>\n<li><em>Queueing-Semantik:</em> Parameter <code>queue length</code> definiert das Aktivierungslimit für die Entität (<code>activations &lt;= queue length</code>).</li>\n<li><strong>Orthogonale Region <code>ModeDisabling</code> (Modus-Aktivierungssteuerung):</strong></li>\n<li><code>enabled</code>: Entität ist für Aktivierung und Ausführung freigegeben (Standardzustand).</li>\n<li><code>disabled</code>: Entität ist durch mindestens einen aktiven Deaktivierungsmodus gesperrt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Partition Life-Cycle (Umfeld-Transitionen)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Eintritt in <code>ExecutableEntity execution-instance is schedulable</code> sobald Guard <code>[RTE / SchM of the partition is running]</code> wahr ist.</li>\n<li><strong>Terminierung:</strong> Austritt in den Endzustand bei <code>[RTE / SchM of the partition is stopped]</code>.</li>\n</ol>\n<p class=\"fig-p\">#### Region <code>ModeDisabling</code> (Modusverwaltung)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Startet im Zustand <code>enabled</code>.</li>\n<li><strong>Moduswechsel:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintritt in deaktivierende Betriebsmodi: Trigger <code>entersDisablingMode</code> $\\rightarrow$ Wechsel nach <code>disabled</code>.</li>\n<li>Verlassen der deaktivierenden Betriebsmodi: Trigger <code>exitsDisablingMode</code> $\\rightarrow$ Wechsel zurück nach <code>enabled</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Region <code>Activation</code> (Ereignissteuerung, Queuing & Modussynchronisation)</p>\n<ol class=\"fig-list\">\n<li><strong>Erste Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>not activated</code> via Event <code>activate</code>: Aktion <code>/activations = 1</code> führt in Zustand <code>debounce activation</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung / Sperrzeit:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>debounce activation</code>: Eintreffende <code>activate</code>-Events inkrementieren bedingt den Zähler (<code>activations += (activations &lt;= queue length) 1:0</code>).</li>\n<li>Sobald Guard <code>[debounceTimer &gt;= minimumStartInterval]</code> erfüllt ist, erfolgt der Übergang in Zustand <code>activated</code>.</li>\n<li>In <code>activated</code>: Eintreffende <code>activate</code>-Events inkrementieren ebenfalls bedingt den Zähler (<code>activations += (activations &lt;= queue length) 1:0</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modus-Deaktivierung und Re-Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wechsel von aktiven zu inaktiven Zuständen bei Guard <code>[ModeDisabling in state disabled]</code>:</li>\n<li><code>not activated</code> $\\rightarrow$ <code>disabled not activated</code></li>\n<li><code>debounce activation</code> $\\rightarrow$ <code>disabled debounce activation</code></li>\n<li><code>activated</code> $\\rightarrow$ <code>disabled activated</code></li>\n<li>Rückkehr bei Guard <code>[ModeDisabling in state enabled]</code>:</li>\n<li><code>disabled not activated</code> $\\rightarrow$ <code>not activated</code></li>\n<li><code>disabled debounce activation</code> $\\rightarrow$ <code>debounce activation</code></li>\n<li><code>disabled activated</code> $\\rightarrow$ <code>activated</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Queue-Abarbeitung & Rücksprung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auf Trigger <code>start</code> (synchronisiert mit Region <code>Main</code>): Aktion <code>/activations -= 1; debounceTimer = 0</code>.</li>\n<li>Verzweigung (Choice-Pseudostate):</li>\n<li><code>[activations == 0]</code> $\\rightarrow$ Rückkehr zu <code>not activated</code>.</li>\n<li><code>[activations &gt; 0]</code> $\\rightarrow$ Übergang zu <code>debounce activation</code>, um verbleibende Aktivierungen unter Einhaltung des <code>minimumStartInterval</code> abzuarbeiten.</li>\n</ul>\n<p class=\"fig-p\">#### Region <code>Main</code> (Ausführungs-Scheduling)</p>\n<ol class=\"fig-list\">\n<li><strong>Start:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>suspended</code> nach <code>to be started</code>, sobald Guard <code>[Activation in state activated]</code> greift.</li>\n<li>Auf Event <code>start</code> $\\rightarrow$ Wechsel in <code>preempted</code> (Task wird vom OS auf <code>READY</code> gesetzt).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Scheduler weist CPU zu: <code>resume</code> $\\rightarrow$ <code>running</code>.</li>\n<li>Bei Verdrängung: <code>preempt</code> $\\rightarrow$ <code>preempted</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation / Blockierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Blocking-Aufruf (nur in Extended Tasks zulässig): <code>wait</code> $\\rightarrow$ <code>waiting</code>.</li>\n<li>Event eintritt / Ressource frei: <code>release</code> $\\rightarrow$ <code>preempted</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Beendigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ende der Runnable-Funktion: <code>terminate</code> $\\rightarrow$ Rückkehr nach <code>suspended</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (<code>minimumStartInterval</code>):</strong> Das im BSW-/SWC-Dossier parametrierte <code>minimumStartInterval</code> schützt den Task vor Überlastung (z. B. bei hochfrequenten CAN-Interrupts oder Event-Triggerung). Ein zu groß gewählter Wert führt zu Latenzen bei Folgeaktivierungen; ein zu kleiner Wert kann CPU-Starvation niederpriorer Tasks begünstigen.</li>\n<li><strong>Queue-Überlauf (<code>queue length</code>):</strong> Übersteigt die Anzahl gleichzeitiger <code>activate</code>-Trigger die konfigurierte Queue-Tiefe, werden weitere Requests verworfen (<code>activations += 0</code>). Dies erfordert für sicherheitskritische Runnables eine exakte Worst-Case-Dimensionierung des Queue-Limits im System Description / EcuExtract.</li>\n<li><strong>Mode-Disabling-Mechanismus:</strong> Über die orthogonale Region <code>ModeDisabling</code> werden ExecutableEntities an RTE-Modi (<code>ModeDeclarationGroup</code>) gekoppelt. Wird ein deaktivierender Modus aktiv (<code>entersDisablingMode</code>), friert die Aktivierungslogik in den entsprechenden <code>disabled ...</code>-Zuständen ein. Da der Dispatching-Trigger in Region <code>Main</code> an <code>[Activation in state activated]</code> gebunden ist, werden in deaktivierten Modi keine neuen Task-Aktivierungen angestoßen.</li>\n<li><strong>Task-Typ-Restriktionen (Basic vs. Extended Task):</strong></li>\n<li>Die Transitionen <code>wait</code> und <code>release</code> setzen zwingend einen <strong>Extended Task</strong> (OSEK-Events) voraus.</li>\n<li>Wird eine <code>ExecutableEntity</code> auf einen <strong>Basic Task</strong> gemappt, existiert der Unterzustand <code>waiting</code> zur Laufzeit nicht; der Code darf keine blockierenden RTE-APIs aufrufen (z. B. synchrone Server-Calls mit Warteoperationen).</li>\n<li><strong>RTE-Partitions-Status:</strong> Aktivierungen und Dispatching greifen nur, wenn die Partition der SWC/BSW gestartet ist (<code>Rte_Start()</code> / SchM-Init ausgeführt). Aufrufe oder Trigger im gestoppten Zustand bleiben inaktiv.</li>\n</ul>"}, {"id": "FIG-7f0ef3f642943c80", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>State Machine Diagram</em>) mit drei orthogonalen (nebenläufigen) Regionen (<code>Main</code>, <code>Activation</code> und <code>ModeDisabling</code>) innerhalb des übergeordneten Composite States <code>ExecutableEntity execution-instance is schedulable</code>.</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition des Lebenszyklus, Aktivierungs- und Deaktivierungsverhaltens einer Instanz einer <code>ExecutableEntity</code> (z. B. <code>RunnableEntity</code> eines SWC oder <code>BswSchedulableEntity</code> des BSW-Schedulers SchM) in der AUTOSAR Runtime Environment (RTE).</li>\n<li><strong>Architektonische Einordnung:</strong> Bindeglied zwischen RTE-Aktivierungstriggern (Events, Timer, Data-Received-Events), Modusverwaltung (<code>ModeDeclarationGroup</code>, Modus-Deaktivierung) und dem AUTOSAR-OS-Taskmanagement. Das Modell bildet ab, wie Aktivierungsanforderungen gepuffert, entprellt (<code>minimumStartInterval</code>), durch Betriebsmodi freigegeben oder gesperrt (<code>ModeDisabling</code>) und auf die Betriebssystem-Taskzustände (<em>suspended</em>, <em>ready</em>, <em>running</em>, <em>waiting</em>) synchronisiert werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustandsraum-Variablen & Timer:</strong></li>\n<li><code>activations: int = 0</code>: Zähler für anstehende Ausführungsanforderungen (Aktivierungs-Queue).</li>\n<li><code>«continuously increasing timer» - debounceTimer: float = minimumStartInterval</code>: Kontinuierlich laufender Hardware-/OS-Timer zur Durchsetzung des Mindestabstands aufeinanderfolgender Starts (<code>minimumStartInterval</code>).</li>\n<li><strong>Orthogonale Region <code>Main</code> (Ausführungszustände im OS-Kontext):</strong></li>\n<li><code>suspended</code>: Entität ist inaktiv; keine Ausführungsanforderung aktiv.</li>\n<li><code>to be started</code>: Aktivierung liegt vor (<code>Activation</code> in <code>activated</code>), Entität wartet auf Dispatching durch das OS.</li>\n<li><code>started</code> (Composite State):</li>\n<li><code>running</code>: Entität belegt aktuell den Prozessorkern (führt Code aus).</li>\n<li><code>waiting</code>: Entität blockiert auf ein OS-Event (<code>wait</code>, z. B. Rte_Receive/Rte_Feedback bei Server-Calls/Inter-Runnable-Synchronisation).</li>\n<li><code>preempted</code>: Unterbrochen durch höher priorisierten Task oder ISR (<code>preempt</code>).</li>\n<li><em>OS-Zuordnung:</em> Die Zustände <code>to be started</code> und <code>preempted</code> korrespondieren direkt mit dem OSEK/AUTOSAR-Task-Zustand <strong>READY</strong>.</li>\n<li><strong>Orthogonale Region <code>Activation</code> (Aktivierungs-, Entprell- & Modussperr-Logik):</strong></li>\n<li>Aktive Zustände:</li>\n<li><code>not activated</code>: Keine ausstehende Aktivierung vorhanden.</li>\n<li><code>debounce activation</code>: Aktivierung empfangen, Sperrzeit (<code>minimumStartInterval</code>) läuft.</li>\n<li><code>activated</code>: Ausführungsbedingung erfüllt; Entität ist startbereit für die <code>Main</code>-Region.</li>\n<li>Deaktivierte Zustände (gesperrt durch Modus):</li>\n<li><code>disabled not activated</code>: Deaktivierter Grundzustand ohne anstehende Aktivierung.</li>\n<li><code>disabled debounce activation</code>: Deaktivierter Zustand während laufendem Debounce-Timer.</li>\n<li><code>disabled activated</code>: Deaktivierter Zustand mit bereits abgelaufenem Mindestabstand.</li>\n<li><em>Queueing-Semantik:</em> Parameter <code>queue length</code> definiert das Aktivierungslimit für die Entität (<code>activations &lt;= queue length</code>).</li>\n<li><strong>Orthogonale Region <code>ModeDisabling</code> (Modus-Aktivierungssteuerung):</strong></li>\n<li><code>enabled</code>: Entität ist für Aktivierung und Ausführung freigegeben (Standardzustand).</li>\n<li><code>disabled</code>: Entität ist durch mindestens einen aktiven Deaktivierungsmodus gesperrt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Partition Life-Cycle (Umfeld-Transitionen)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Eintritt in <code>ExecutableEntity execution-instance is schedulable</code> sobald Guard <code>[RTE / SchM of the partition is running]</code> wahr ist.</li>\n<li><strong>Terminierung:</strong> Austritt in den Endzustand bei <code>[RTE / SchM of the partition is stopped]</code>.</li>\n</ol>\n<p class=\"fig-p\">#### Region <code>ModeDisabling</code> (Modusverwaltung)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Startet im Zustand <code>enabled</code>.</li>\n<li><strong>Moduswechsel:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintritt in deaktivierende Betriebsmodi: Trigger <code>entersDisablingMode</code> $\\rightarrow$ Wechsel nach <code>disabled</code>.</li>\n<li>Verlassen der deaktivierenden Betriebsmodi: Trigger <code>exitsDisablingMode</code> $\\rightarrow$ Wechsel zurück nach <code>enabled</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Region <code>Activation</code> (Ereignissteuerung, Queuing & Modussynchronisation)</p>\n<ol class=\"fig-list\">\n<li><strong>Erste Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>not activated</code> via Event <code>activate</code>: Aktion <code>/activations = 1</code> führt in Zustand <code>debounce activation</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung / Sperrzeit:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>debounce activation</code>: Eintreffende <code>activate</code>-Events inkrementieren bedingt den Zähler (<code>activations += (activations &lt;= queue length) 1:0</code>).</li>\n<li>Sobald Guard <code>[debounceTimer &gt;= minimumStartInterval]</code> erfüllt ist, erfolgt der Übergang in Zustand <code>activated</code>.</li>\n<li>In <code>activated</code>: Eintreffende <code>activate</code>-Events inkrementieren ebenfalls bedingt den Zähler (<code>activations += (activations &lt;= queue length) 1:0</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modus-Deaktivierung und Re-Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wechsel von aktiven zu inaktiven Zuständen bei Guard <code>[ModeDisabling in state disabled]</code>:</li>\n<li><code>not activated</code> $\\rightarrow$ <code>disabled not activated</code></li>\n<li><code>debounce activation</code> $\\rightarrow$ <code>disabled debounce activation</code></li>\n<li><code>activated</code> $\\rightarrow$ <code>disabled activated</code></li>\n<li>Rückkehr bei Guard <code>[ModeDisabling in state enabled]</code>:</li>\n<li><code>disabled not activated</code> $\\rightarrow$ <code>not activated</code></li>\n<li><code>disabled debounce activation</code> $\\rightarrow$ <code>debounce activation</code></li>\n<li><code>disabled activated</code> $\\rightarrow$ <code>activated</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Queue-Abarbeitung & Rücksprung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auf Trigger <code>start</code> (synchronisiert mit Region <code>Main</code>): Aktion <code>/activations -= 1; debounceTimer = 0</code>.</li>\n<li>Verzweigung (Choice-Pseudostate):</li>\n<li><code>[activations == 0]</code> $\\rightarrow$ Rückkehr zu <code>not activated</code>.</li>\n<li><code>[activations &gt; 0]</code> $\\rightarrow$ Übergang zu <code>debounce activation</code>, um verbleibende Aktivierungen unter Einhaltung des <code>minimumStartInterval</code> abzuarbeiten.</li>\n</ul>\n<p class=\"fig-p\">#### Region <code>Main</code> (Ausführungs-Scheduling)</p>\n<ol class=\"fig-list\">\n<li><strong>Start:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>suspended</code> nach <code>to be started</code>, sobald Guard <code>[Activation in state activated]</code> greift.</li>\n<li>Auf Event <code>start</code> $\\rightarrow$ Wechsel in <code>preempted</code> (Task wird vom OS auf <code>READY</code> gesetzt).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Scheduler weist CPU zu: <code>resume</code> $\\rightarrow$ <code>running</code>.</li>\n<li>Bei Verdrängung: <code>preempt</code> $\\rightarrow$ <code>preempted</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation / Blockierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Blocking-Aufruf (nur in Extended Tasks zulässig): <code>wait</code> $\\rightarrow$ <code>waiting</code>.</li>\n<li>Event eintritt / Ressource frei: <code>release</code> $\\rightarrow$ <code>preempted</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Beendigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ende der Runnable-Funktion: <code>terminate</code> $\\rightarrow$ Rückkehr nach <code>suspended</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (<code>minimumStartInterval</code>):</strong> Das im BSW-/SWC-Dossier parametrierte <code>minimumStartInterval</code> schützt den Task vor Überlastung (z. B. bei hochfrequenten CAN-Interrupts oder Event-Triggerung). Ein zu groß gewählter Wert führt zu Latenzen bei Folgeaktivierungen; ein zu kleiner Wert kann CPU-Starvation niederpriorer Tasks begünstigen.</li>\n<li><strong>Queue-Überlauf (<code>queue length</code>):</strong> Übersteigt die Anzahl gleichzeitiger <code>activate</code>-Trigger die konfigurierte Queue-Tiefe, werden weitere Requests verworfen (<code>activations += 0</code>). Dies erfordert für sicherheitskritische Runnables eine exakte Worst-Case-Dimensionierung des Queue-Limits im System Description / EcuExtract.</li>\n<li><strong>Mode-Disabling-Mechanismus:</strong> Über die orthogonale Region <code>ModeDisabling</code> werden ExecutableEntities an RTE-Modi (<code>ModeDeclarationGroup</code>) gekoppelt. Wird ein deaktivierender Modus aktiv (<code>entersDisablingMode</code>), friert die Aktivierungslogik in den entsprechenden <code>disabled ...</code>-Zuständen ein. Da der Dispatching-Trigger in Region <code>Main</code> an <code>[Activation in state activated]</code> gebunden ist, werden in deaktivierten Modi keine neuen Task-Aktivierungen angestoßen.</li>\n<li><strong>Task-Typ-Restriktionen (Basic vs. Extended Task):</strong></li>\n<li>Die Transitionen <code>wait</code> und <code>release</code> setzen zwingend einen <strong>Extended Task</strong> (OSEK-Events) voraus.</li>\n<li>Wird eine <code>ExecutableEntity</code> auf einen <strong>Basic Task</strong> gemappt, existiert der Unterzustand <code>waiting</code> zur Laufzeit nicht; der Code darf keine blockierenden RTE-APIs aufrufen (z. B. synchrone Server-Calls mit Warteoperationen).</li>\n<li><strong>RTE-Partitions-Status:</strong> Aktivierungen und Dispatching greifen nur, wenn die Partition der SWC/BSW gestartet ist (<code>Rte_Start()</code> / SchM-Init ausgeführt). Aufrufe oder Trigger im gestoppten Zustand bleiben inaktiv.</li>\n</ul>"}, {"id": "FIG-6f08a07ac3563964", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>State Machine Diagram</em>) mit drei orthogonalen (nebenläufigen) Regionen (<code>Main</code>, <code>Activation</code> und <code>ModeDisabling</code>) innerhalb des übergeordneten Composite States <code>ExecutableEntity execution-instance is schedulable</code>.</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition des Lebenszyklus, Aktivierungs- und Deaktivierungsverhaltens einer Instanz einer <code>ExecutableEntity</code> (z. B. <code>RunnableEntity</code> eines SWC oder <code>BswSchedulableEntity</code> des BSW-Schedulers SchM) in der AUTOSAR Runtime Environment (RTE).</li>\n<li><strong>Architektonische Einordnung:</strong> Bindeglied zwischen RTE-Aktivierungstriggern (Events, Timer, Data-Received-Events), Modusverwaltung (<code>ModeDeclarationGroup</code>, Modus-Deaktivierung) und dem AUTOSAR-OS-Taskmanagement. Das Modell bildet ab, wie Aktivierungsanforderungen gepuffert, entprellt (<code>minimumStartInterval</code>), durch Betriebsmodi freigegeben oder gesperrt (<code>ModeDisabling</code>) und auf die Betriebssystem-Taskzustände (<em>suspended</em>, <em>ready</em>, <em>running</em>, <em>waiting</em>) synchronisiert werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustandsraum-Variablen & Timer:</strong></li>\n<li><code>activations: int = 0</code>: Zähler für anstehende Ausführungsanforderungen (Aktivierungs-Queue).</li>\n<li><code>«continuously increasing timer» - debounceTimer: float = minimumStartInterval</code>: Kontinuierlich laufender Hardware-/OS-Timer zur Durchsetzung des Mindestabstands aufeinanderfolgender Starts (<code>minimumStartInterval</code>).</li>\n<li><strong>Orthogonale Region <code>Main</code> (Ausführungszustände im OS-Kontext):</strong></li>\n<li><code>suspended</code>: Entität ist inaktiv; keine Ausführungsanforderung aktiv.</li>\n<li><code>to be started</code>: Aktivierung liegt vor (<code>Activation</code> in <code>activated</code>), Entität wartet auf Dispatching durch das OS.</li>\n<li><code>started</code> (Composite State):</li>\n<li><code>running</code>: Entität belegt aktuell den Prozessorkern (führt Code aus).</li>\n<li><code>waiting</code>: Entität blockiert auf ein OS-Event (<code>wait</code>, z. B. Rte_Receive/Rte_Feedback bei Server-Calls/Inter-Runnable-Synchronisation).</li>\n<li><code>preempted</code>: Unterbrochen durch höher priorisierten Task oder ISR (<code>preempt</code>).</li>\n<li><em>OS-Zuordnung:</em> Die Zustände <code>to be started</code> und <code>preempted</code> korrespondieren direkt mit dem OSEK/AUTOSAR-Task-Zustand <strong>READY</strong>.</li>\n<li><strong>Orthogonale Region <code>Activation</code> (Aktivierungs-, Entprell- & Modussperr-Logik):</strong></li>\n<li>Aktive Zustände:</li>\n<li><code>not activated</code>: Keine ausstehende Aktivierung vorhanden.</li>\n<li><code>debounce activation</code>: Aktivierung empfangen, Sperrzeit (<code>minimumStartInterval</code>) läuft.</li>\n<li><code>activated</code>: Ausführungsbedingung erfüllt; Entität ist startbereit für die <code>Main</code>-Region.</li>\n<li>Deaktivierte Zustände (gesperrt durch Modus):</li>\n<li><code>disabled not activated</code>: Deaktivierter Grundzustand ohne anstehende Aktivierung.</li>\n<li><code>disabled debounce activation</code>: Deaktivierter Zustand während laufendem Debounce-Timer.</li>\n<li><code>disabled activated</code>: Deaktivierter Zustand mit bereits abgelaufenem Mindestabstand.</li>\n<li><em>Queueing-Semantik:</em> Parameter <code>queue length</code> definiert das Aktivierungslimit für die Entität (<code>activations &lt;= queue length</code>).</li>\n<li><strong>Orthogonale Region <code>ModeDisabling</code> (Modus-Aktivierungssteuerung):</strong></li>\n<li><code>enabled</code>: Entität ist für Aktivierung und Ausführung freigegeben (Standardzustand).</li>\n<li><code>disabled</code>: Entität ist durch mindestens einen aktiven Deaktivierungsmodus gesperrt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Partition Life-Cycle (Umfeld-Transitionen)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Eintritt in <code>ExecutableEntity execution-instance is schedulable</code> sobald Guard <code>[RTE / SchM of the partition is running]</code> wahr ist.</li>\n<li><strong>Terminierung:</strong> Austritt in den Endzustand bei <code>[RTE / SchM of the partition is stopped]</code>.</li>\n</ol>\n<p class=\"fig-p\">#### Region <code>ModeDisabling</code> (Modusverwaltung)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Startet im Zustand <code>enabled</code>.</li>\n<li><strong>Moduswechsel:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintritt in deaktivierende Betriebsmodi: Trigger <code>entersDisablingMode</code> $\\rightarrow$ Wechsel nach <code>disabled</code>.</li>\n<li>Verlassen der deaktivierenden Betriebsmodi: Trigger <code>exitsDisablingMode</code> $\\rightarrow$ Wechsel zurück nach <code>enabled</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Region <code>Activation</code> (Ereignissteuerung, Queuing & Modussynchronisation)</p>\n<ol class=\"fig-list\">\n<li><strong>Erste Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>not activated</code> via Event <code>activate</code>: Aktion <code>/activations = 1</code> führt in Zustand <code>debounce activation</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung / Sperrzeit:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>debounce activation</code>: Eintreffende <code>activate</code>-Events inkrementieren bedingt den Zähler (<code>activations += (activations &lt;= queue length) 1:0</code>).</li>\n<li>Sobald Guard <code>[debounceTimer &gt;= minimumStartInterval]</code> erfüllt ist, erfolgt der Übergang in Zustand <code>activated</code>.</li>\n<li>In <code>activated</code>: Eintreffende <code>activate</code>-Events inkrementieren ebenfalls bedingt den Zähler (<code>activations += (activations &lt;= queue length) 1:0</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modus-Deaktivierung und Re-Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wechsel von aktiven zu inaktiven Zuständen bei Guard <code>[ModeDisabling in state disabled]</code>:</li>\n<li><code>not activated</code> $\\rightarrow$ <code>disabled not activated</code></li>\n<li><code>debounce activation</code> $\\rightarrow$ <code>disabled debounce activation</code></li>\n<li><code>activated</code> $\\rightarrow$ <code>disabled activated</code></li>\n<li>Rückkehr bei Guard <code>[ModeDisabling in state enabled]</code>:</li>\n<li><code>disabled not activated</code> $\\rightarrow$ <code>not activated</code></li>\n<li><code>disabled debounce activation</code> $\\rightarrow$ <code>debounce activation</code></li>\n<li><code>disabled activated</code> $\\rightarrow$ <code>activated</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Queue-Abarbeitung & Rücksprung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auf Trigger <code>start</code> (synchronisiert mit Region <code>Main</code>): Aktion <code>/activations -= 1; debounceTimer = 0</code>.</li>\n<li>Verzweigung (Choice-Pseudostate):</li>\n<li><code>[activations == 0]</code> $\\rightarrow$ Rückkehr zu <code>not activated</code>.</li>\n<li><code>[activations &gt; 0]</code> $\\rightarrow$ Übergang zu <code>debounce activation</code>, um verbleibende Aktivierungen unter Einhaltung des <code>minimumStartInterval</code> abzuarbeiten.</li>\n</ul>\n<p class=\"fig-p\">#### Region <code>Main</code> (Ausführungs-Scheduling)</p>\n<ol class=\"fig-list\">\n<li><strong>Start:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>suspended</code> nach <code>to be started</code>, sobald Guard <code>[Activation in state activated]</code> greift.</li>\n<li>Auf Event <code>start</code> $\\rightarrow$ Wechsel in <code>preempted</code> (Task wird vom OS auf <code>READY</code> gesetzt).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Scheduler weist CPU zu: <code>resume</code> $\\rightarrow$ <code>running</code>.</li>\n<li>Bei Verdrängung: <code>preempt</code> $\\rightarrow$ <code>preempted</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation / Blockierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Blocking-Aufruf (nur in Extended Tasks zulässig): <code>wait</code> $\\rightarrow$ <code>waiting</code>.</li>\n<li>Event eintritt / Ressource frei: <code>release</code> $\\rightarrow$ <code>preempted</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Beendigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ende der Runnable-Funktion: <code>terminate</code> $\\rightarrow$ Rückkehr nach <code>suspended</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (<code>minimumStartInterval</code>):</strong> Das im BSW-/SWC-Dossier parametrierte <code>minimumStartInterval</code> schützt den Task vor Überlastung (z. B. bei hochfrequenten CAN-Interrupts oder Event-Triggerung). Ein zu groß gewählter Wert führt zu Latenzen bei Folgeaktivierungen; ein zu kleiner Wert kann CPU-Starvation niederpriorer Tasks begünstigen.</li>\n<li><strong>Queue-Überlauf (<code>queue length</code>):</strong> Übersteigt die Anzahl gleichzeitiger <code>activate</code>-Trigger die konfigurierte Queue-Tiefe, werden weitere Requests verworfen (<code>activations += 0</code>). Dies erfordert für sicherheitskritische Runnables eine exakte Worst-Case-Dimensionierung des Queue-Limits im System Description / EcuExtract.</li>\n<li><strong>Mode-Disabling-Mechanismus:</strong> Über die orthogonale Region <code>ModeDisabling</code> werden ExecutableEntities an RTE-Modi (<code>ModeDeclarationGroup</code>) gekoppelt. Wird ein deaktivierender Modus aktiv (<code>entersDisablingMode</code>), friert die Aktivierungslogik in den entsprechenden <code>disabled ...</code>-Zuständen ein. Da der Dispatching-Trigger in Region <code>Main</code> an <code>[Activation in state activated]</code> gebunden ist, werden in deaktivierten Modi keine neuen Task-Aktivierungen angestoßen.</li>\n<li><strong>Task-Typ-Restriktionen (Basic vs. Extended Task):</strong></li>\n<li>Die Transitionen <code>wait</code> und <code>release</code> setzen zwingend einen <strong>Extended Task</strong> (OSEK-Events) voraus.</li>\n<li>Wird eine <code>ExecutableEntity</code> auf einen <strong>Basic Task</strong> gemappt, existiert der Unterzustand <code>waiting</code> zur Laufzeit nicht; der Code darf keine blockierenden RTE-APIs aufrufen (z. B. synchrone Server-Calls mit Warteoperationen).</li>\n<li><strong>RTE-Partitions-Status:</strong> Aktivierungen und Dispatching greifen nur, wenn die Partition der SWC/BSW gestartet ist (<code>Rte_Start()</code> / SchM-Init ausgeführt). Aufrufe oder Trigger im gestoppten Zustand bleiben inaktiv.</li>\n</ul>"}, {"id": "FIG-e0eaf194b762a8b5", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Zustandsautomat (<em>State Machine Diagram</em>) mit drei orthogonalen (nebenläufigen) Regionen (<code>Main</code>, <code>Activation</code> und <code>ModeDisabling</code>) innerhalb des übergeordneten Composite States <code>ExecutableEntity execution-instance is schedulable</code>.</li>\n<li><strong>Technischer Zweck:</strong> Formale Definition des Lebenszyklus, Aktivierungs- und Deaktivierungsverhaltens einer Instanz einer <code>ExecutableEntity</code> (z. B. <code>RunnableEntity</code> eines SWC oder <code>BswSchedulableEntity</code> des BSW-Schedulers SchM) in der AUTOSAR Runtime Environment (RTE).</li>\n<li><strong>Architektonische Einordnung:</strong> Bindeglied zwischen RTE-Aktivierungstriggern (Events, Timer, Data-Received-Events), Modusverwaltung (<code>ModeDeclarationGroup</code>, Modus-Deaktivierung) und dem AUTOSAR-OS-Taskmanagement. Das Modell bildet ab, wie Aktivierungsanforderungen gepuffert, entprellt (<code>minimumStartInterval</code>), durch Betriebsmodi freigegeben oder gesperrt (<code>ModeDisabling</code>) und auf die Betriebssystem-Taskzustände (<em>suspended</em>, <em>ready</em>, <em>running</em>, <em>waiting</em>) synchronisiert werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Zustandsraum-Variablen & Timer:</strong></li>\n<li><code>activations: int = 0</code>: Zähler für anstehende Ausführungsanforderungen (Aktivierungs-Queue).</li>\n<li><code>«continuously increasing timer» - debounceTimer: float = minimumStartInterval</code>: Kontinuierlich laufender Hardware-/OS-Timer zur Durchsetzung des Mindestabstands aufeinanderfolgender Starts (<code>minimumStartInterval</code>).</li>\n<li><strong>Orthogonale Region <code>Main</code> (Ausführungszustände im OS-Kontext):</strong></li>\n<li><code>suspended</code>: Entität ist inaktiv; keine Ausführungsanforderung aktiv.</li>\n<li><code>to be started</code>: Aktivierung liegt vor (<code>Activation</code> in <code>activated</code>), Entität wartet auf Dispatching durch das OS.</li>\n<li><code>started</code> (Composite State):</li>\n<li><code>running</code>: Entität belegt aktuell den Prozessorkern (führt Code aus).</li>\n<li><code>waiting</code>: Entität blockiert auf ein OS-Event (<code>wait</code>, z. B. Rte_Receive/Rte_Feedback bei Server-Calls/Inter-Runnable-Synchronisation).</li>\n<li><code>preempted</code>: Unterbrochen durch höher priorisierten Task oder ISR (<code>preempt</code>).</li>\n<li><em>OS-Zuordnung:</em> Die Zustände <code>to be started</code> und <code>preempted</code> korrespondieren direkt mit dem OSEK/AUTOSAR-Task-Zustand <strong>READY</strong>.</li>\n<li><strong>Orthogonale Region <code>Activation</code> (Aktivierungs-, Entprell- & Modussperr-Logik):</strong></li>\n<li>Aktive Zustände:</li>\n<li><code>not activated</code>: Keine ausstehende Aktivierung vorhanden.</li>\n<li><code>debounce activation</code>: Aktivierung empfangen, Sperrzeit (<code>minimumStartInterval</code>) läuft.</li>\n<li><code>activated</code>: Ausführungsbedingung erfüllt; Entität ist startbereit für die <code>Main</code>-Region.</li>\n<li>Deaktivierte Zustände (gesperrt durch Modus):</li>\n<li><code>disabled not activated</code>: Deaktivierter Grundzustand ohne anstehende Aktivierung.</li>\n<li><code>disabled debounce activation</code>: Deaktivierter Zustand während laufendem Debounce-Timer.</li>\n<li><code>disabled activated</code>: Deaktivierter Zustand mit bereits abgelaufenem Mindestabstand.</li>\n<li><em>Queueing-Semantik:</em> Parameter <code>queue length</code> definiert das Aktivierungslimit für die Entität (<code>activations &lt;= queue length</code>).</li>\n<li><strong>Orthogonale Region <code>ModeDisabling</code> (Modus-Aktivierungssteuerung):</strong></li>\n<li><code>enabled</code>: Entität ist für Aktivierung und Ausführung freigegeben (Standardzustand).</li>\n<li><code>disabled</code>: Entität ist durch mindestens einen aktiven Deaktivierungsmodus gesperrt.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">#### Partition Life-Cycle (Umfeld-Transitionen)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Eintritt in <code>ExecutableEntity execution-instance is schedulable</code> sobald Guard <code>[RTE / SchM of the partition is running]</code> wahr ist.</li>\n<li><strong>Terminierung:</strong> Austritt in den Endzustand bei <code>[RTE / SchM of the partition is stopped]</code>.</li>\n</ol>\n<p class=\"fig-p\">#### Region <code>ModeDisabling</code> (Modusverwaltung)</p>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung:</strong> Startet im Zustand <code>enabled</code>.</li>\n<li><strong>Moduswechsel:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Eintritt in deaktivierende Betriebsmodi: Trigger <code>entersDisablingMode</code> $\\rightarrow$ Wechsel nach <code>disabled</code>.</li>\n<li>Verlassen der deaktivierenden Betriebsmodi: Trigger <code>exitsDisablingMode</code> $\\rightarrow$ Wechsel zurück nach <code>enabled</code>.</li>\n</ul>\n<p class=\"fig-p\">#### Region <code>Activation</code> (Ereignissteuerung, Queuing & Modussynchronisation)</p>\n<ol class=\"fig-list\">\n<li><strong>Erste Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Aus <code>not activated</code> via Event <code>activate</code>: Aktion <code>/activations = 1</code> führt in Zustand <code>debounce activation</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Entprellung / Sperrzeit:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>In <code>debounce activation</code>: Eintreffende <code>activate</code>-Events inkrementieren bedingt den Zähler (<code>activations += (activations &lt;= queue length) 1:0</code>).</li>\n<li>Sobald Guard <code>[debounceTimer &gt;= minimumStartInterval]</code> erfüllt ist, erfolgt der Übergang in Zustand <code>activated</code>.</li>\n<li>In <code>activated</code>: Eintreffende <code>activate</code>-Events inkrementieren ebenfalls bedingt den Zähler (<code>activations += (activations &lt;= queue length) 1:0</code>).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Modus-Deaktivierung und Re-Aktivierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wechsel von aktiven zu inaktiven Zuständen bei Guard <code>[ModeDisabling in state disabled]</code>:</li>\n<li><code>not activated</code> $\\rightarrow$ <code>disabled not activated</code></li>\n<li><code>debounce activation</code> $\\rightarrow$ <code>disabled debounce activation</code></li>\n<li><code>activated</code> $\\rightarrow$ <code>disabled activated</code></li>\n<li>Rückkehr bei Guard <code>[ModeDisabling in state enabled]</code>:</li>\n<li><code>disabled not activated</code> $\\rightarrow$ <code>not activated</code></li>\n<li><code>disabled debounce activation</code> $\\rightarrow$ <code>debounce activation</code></li>\n<li><code>disabled activated</code> $\\rightarrow$ <code>activated</code></li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Queue-Abarbeitung & Rücksprung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Auf Trigger <code>start</code> (synchronisiert mit Region <code>Main</code>): Aktion <code>/activations -= 1; debounceTimer = 0</code>.</li>\n<li>Verzweigung (Choice-Pseudostate):</li>\n<li><code>[activations == 0]</code> $\\rightarrow$ Rückkehr zu <code>not activated</code>.</li>\n<li><code>[activations &gt; 0]</code> $\\rightarrow$ Übergang zu <code>debounce activation</code>, um verbleibende Aktivierungen unter Einhaltung des <code>minimumStartInterval</code> abzuarbeiten.</li>\n</ul>\n<p class=\"fig-p\">#### Region <code>Main</code> (Ausführungs-Scheduling)</p>\n<ol class=\"fig-list\">\n<li><strong>Start:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Von <code>suspended</code> nach <code>to be started</code>, sobald Guard <code>[Activation in state activated]</code> greift.</li>\n<li>Auf Event <code>start</code> $\\rightarrow$ Wechsel in <code>preempted</code> (Task wird vom OS auf <code>READY</code> gesetzt).</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Ausführung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Scheduler weist CPU zu: <code>resume</code> $\\rightarrow$ <code>running</code>.</li>\n<li>Bei Verdrängung: <code>preempt</code> $\\rightarrow$ <code>preempted</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Synchronisation / Blockierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Blocking-Aufruf (nur in Extended Tasks zulässig): <code>wait</code> $\\rightarrow$ <code>waiting</code>.</li>\n<li>Event eintritt / Ressource frei: <code>release</code> $\\rightarrow$ <code>preempted</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Beendigung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Ende der Runnable-Funktion: <code>terminate</code> $\\rightarrow$ Rückkehr nach <code>suspended</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Konfiguration (<code>minimumStartInterval</code>):</strong> Das im BSW-/SWC-Dossier parametrierte <code>minimumStartInterval</code> schützt den Task vor Überlastung (z. B. bei hochfrequenten CAN-Interrupts oder Event-Triggerung). Ein zu groß gewählter Wert führt zu Latenzen bei Folgeaktivierungen; ein zu kleiner Wert kann CPU-Starvation niederpriorer Tasks begünstigen.</li>\n<li><strong>Queue-Überlauf (<code>queue length</code>):</strong> Übersteigt die Anzahl gleichzeitiger <code>activate</code>-Trigger die konfigurierte Queue-Tiefe, werden weitere Requests verworfen (<code>activations += 0</code>). Dies erfordert für sicherheitskritische Runnables eine exakte Worst-Case-Dimensionierung des Queue-Limits im System Description / EcuExtract.</li>\n<li><strong>Mode-Disabling-Mechanismus:</strong> Über die orthogonale Region <code>ModeDisabling</code> werden ExecutableEntities an RTE-Modi (<code>ModeDeclarationGroup</code>) gekoppelt. Wird ein deaktivierender Modus aktiv (<code>entersDisablingMode</code>), friert die Aktivierungslogik in den entsprechenden <code>disabled ...</code>-Zuständen ein. Da der Dispatching-Trigger in Region <code>Main</code> an <code>[Activation in state activated]</code> gebunden ist, werden in deaktivierten Modi keine neuen Task-Aktivierungen angestoßen.</li>\n<li><strong>Task-Typ-Restriktionen (Basic vs. Extended Task):</strong></li>\n<li>Die Transitionen <code>wait</code> und <code>release</code> setzen zwingend einen <strong>Extended Task</strong> (OSEK-Events) voraus.</li>\n<li>Wird eine <code>ExecutableEntity</code> auf einen <strong>Basic Task</strong> gemappt, existiert der Unterzustand <code>waiting</code> zur Laufzeit nicht; der Code darf keine blockierenden RTE-APIs aufrufen (z. B. synchrone Server-Calls mit Warteoperationen).</li>\n<li><strong>RTE-Partitions-Status:</strong> Aktivierungen und Dispatching greifen nur, wenn die Partition der SWC/BSW gestartet ist (<code>Rte_Start()</code> / SchM-Init ausgeführt). Aufrufe oder Trigger im gestoppten Zustand bleiben inaktiv.</li>\n</ul>"}], "trans": [{"from": "FIG-8751ea2e074e1b27", "to": "FIG-48ed5424c916017f", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Ergänzung der orthogonalen Region <code>ModeDisabling</code> mit den Zuständen <code>enabled</code> (Initialzustand) und <code>disabled</code> sowie den Transitionen <code>entersDisablingMode</code> und <code>exitsDisablingMode</code>.</li>\n<li>Erweiterung der orthogonalen Region <code>Activation</code> um drei modusspezifisch deaktivierte Zustände: <code>disabled not activated</code>, <code>disabled debounce activation</code> und <code>disabled activated</code>.</li>\n<li>Hinzufügung paarweiser Transitionen zwischen den aktiven und deaktivierten Zuständen in <code>Activation</code>, jeweils bewacht durch <code>[ModeDisabling in state disabled]</code> bzw. <code>[ModeDisabling in state enabled]</code>.</li>\n<li>Redaktionelle Anpassung der Variablenanzeige: Stereotype <code>«continuously increasing timer»</code> bei <code>debounceTimer</code> mit typografischen Guillemets ausgezeichnet und Diagramm-Präfix im Kopf von <code>sm</code> auf <code>stm</code> aktualisiert.</li>\n</ul>"}, {"from": "FIG-48ed5424c916017f", "to": "FIG-7f0ef3f642943c80", "fr": "R4.1.3", "tr": "R4.2.2", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Entfernung des äußeren UML-Rahmens samt Titellasche (<code>stm state machine for an ExecutableEntity execution-instance</code>).</li>\n<li>Am oberen Bildrand wurde versehentlich eine Textzeile des Dokuments („by using a state machine (Fig. 4.17).“) mitgerendert. Das Zustandsdiagramm selbst ist inhaltlich unverändert.</li>\n</ul>"}, {"from": "FIG-7f0ef3f642943c80", "to": "FIG-6f08a07ac3563964", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6f08a07ac3563964", "to": "FIG-e0eaf194b762a8b5", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Entfernung der am oberen Rand fälschlich mitgerenderten Fließtextzeile („by using a state machine (Fig. 4.17).“).</li>\n<li>Drehung des Schaubilds um 90° gegen den Uhrzeigersinn (Querformat-Einbettung im Hochformat-Seitenlayout). Inhaltlich unverändert.</li>\n</ul>"}]};
